              'מוציאים גורם משותף: $\\cos^2 x\\,(k^2 + 1) = 1$.',
              'מבודדים: $\\cos^2 x = \\dfrac{1}{1 + k^2}$.',
              'מוציאים שורש, ומתקבלות שתי אפשרויות: $\\cos x = \\pm\\dfrac{1}{\\sqrt{1 + k^2}}$.',
