              'מציבים בנוסחת הסינוס של הזווית הכפולה: $\\sin 2x = 2\\cdot\\left(-\\dfrac{k}{\\sqrt{1 + k^2}}\\right)\\cdot\\left(-\\dfrac{1}{\\sqrt{1 + k^2}}\\right)$.',
              'מכפילים, ושני הסימנים השליליים נותנים תוצאה חיובית: $\\sin 2x = \\dfrac{2k}{1 + k^2}$.',
              'מציבים בצורה $\\cos 2x = \\cos^2 x - \\sin^2 x$: $\\cos 2x = \\dfrac{1}{1 + k^2} - \\dfrac{k^2}{1 + k^2}$.',
